import React, { useState } from 'react';
import DeckGL from '@deck.gl/react';
import { PolygonLayer } from '@deck.gl/layers';
import Map from 'react-map-gl/mapbox';
import mockData from '../data/mockFarmData.json';



// Center of our sample farm
const INITIAL_VIEW_STATE = {
  longitude: -121.743,
  latitude: 36.673,
  zoom: 15,
  pitch: 45, // 3D tilt
  bearing: 0
};

// Color rule: Green for healthy, Yellow for mild, Red for high risk
function getRiskColor(riskScore) {
  if (riskScore >= 0.7) return [239, 68, 68, 160];  // Red
  if (riskScore >= 0.4) return [245, 158, 11, 160]; // Yellow/Orange
  return [34, 197, 94, 160];                       // Green
}

export default function FarmMap() {
  const [hoverInfo, setHoverInfo] = useState(null);

  // Deck.gl PolygonLayer creates the colored grid over the map
  const heatmapLayer = new PolygonLayer({
    id: 'crop-disease-heatmap',
    data: mockData,
    pickable: true,
    stroked: true,
    filled: true,
    lineWidthMinPixels: 1,
    getPolygon: (d) => d.polygon,
    getFillColor: (d) => getRiskColor(d.riskScore),
    getLineColor: [255, 255, 255, 180],
    onHover: (info) => setHoverInfo(info.object ? info : null)
  });

  return (
    <div style={{ position: 'relative', width: '100vw', height: '100vh' }}>
      <DeckGL
        initialViewState={INITIAL_VIEW_STATE}
        controller={true}
        layers={[heatmapLayer]}
      >
        <Map
          mapboxAccessToken="pk.eyJ1Ijoicml0dW1haGFsaTk2IiwiYSI6ImNtdG9zazR2djAzOG4yd3NkY2ExNnBhdmoifQ._4seILn1UzctGY0lskXptg"
          mapStyle="mapbox://styles/mapbox/satellite-v9"
        />
      </DeckGL>

      {/* Tooltip on hover */}
      {hoverInfo && hoverInfo.object && (
        <div
          style={{
            position: 'absolute',
            zIndex: 10,
            pointerEvents: 'none',
            left: hoverInfo.x + 12,
            top: hoverInfo.y + 12,
            background: '#1f2937',
            color: 'white',
            padding: '8px 12px',
            borderRadius: '6px',
            fontSize: '12px'
          }}
        >
          <div><strong>Status:</strong> {hoverInfo.object.status}</div>
          <div><strong>Risk:</strong> {(hoverInfo.object.riskScore * 100).toFixed(0)}%</div>
          <div><strong>Cell:</strong> {hoverInfo.object.id}</div>
        </div>
      )}

      {/* Legend */}
      <div
        style={{
          position: 'absolute',
          bottom: 20,
          right: 20,
          background: 'white',
          padding: '10px 14px',
          borderRadius: '6px',
          fontSize: '12px',
          boxShadow: '0 2px 6px rgba(0,0,0,0.2)'
        }}
      >
        <div style={{ fontWeight: 'bold', marginBottom: 6 }}>Crop Disease Risk</div>
        <div><span style={{ color: '#22c55e' }}>■</span> Healthy (&lt;40%)</div>
        <div><span style={{ color: '#f59e0b' }}>■</span> Mild Stress (40-70%)</div>
        <div><span style={{ color: '#ef4444' }}>■</span> Blight Outbreak (&gt;70%)</div>
      </div>
    </div>
  );
}
